sys_script.script:
(function executeRule(current, previous /*null when async*/) {
    var patEmail = current.patient ? current.patient.email.toString() : '';
    var patName = current.patient ? current.patient.name.toString() : '';

    // 1. Report Published ('8')
    if (current.status == '8' && (current.operation() == 'insert' || previous.status != '8')) {
        // Patient event
        gs.eventQueue('x_2223823_apollo_0.lab_report_ready', current, patEmail, patName);

        // Doctor event
        gs.eventQueue('x_2223823_apollo_0.doctor_lab_report_ready', current, '', '');
    }

    // 2. Urgent / Emergency Test Ordered
    if (current.urgent == true && (current.operation() == 'insert' || previous.urgent != true)) {
        gs.eventQueue('x_2223823_apollo_0.doctor_urgent_test', current, '', '');
    }
})(current, previous);
